private void InitTrainingLevelPlaceholder()
{
    ddlTrainingLevel.Items.Clear();
    ddlTrainingLevel.Items.Add(new ListItem("Vui lòng chọn Đã tốt nghiệp trước", ""));
    ddlTrainingLevel.Enabled = false;
}
private void InitSpecialBranchPlaceholder()
{
    ddlSpecialBranch.Items.Clear();
    ddlSpecialBranch.Items.Add(new ListItem("--Chọn--", ""));
    ddlSpecialBranch.Enabled = false;
}
private void LoadTrainingLevel()
{
    if (string.IsNullOrEmpty(ddlLearningLevel.SelectedValue))
    {
        InitTrainingLevelPlaceholder();
        return;
    }
    SimsObject.SIM_TrainingLevel objTrainingLevel = new SimsObject.SIM_TrainingLevel();
    ddlTrainingLevel.DataSource = objTrainingLevel.GetDataTable(
                        "SIM_TrainingLevel_SearchForWeb",
                        "@LearningLevelID", ddlLearningLevel.SelectedValue);
    ddlTrainingLevel.DataValueField = "TrainingLevelID";
    ddlTrainingLevel.DataTextField = "TrainingLevelName";
    ddlTrainingLevel.DataBind();
    ddlTrainingLevel.Items.Insert(0, new ListItem("--Chọn--", ""));
    ddlTrainingLevel.Enabled = true;
}

private void LoadSpecialBranch()
{
    if (string.IsNullOrEmpty(ddlLearningLevel.SelectedValue) || string.IsNullOrEmpty(ddlTrainingLevel.SelectedValue))
    {
        InitSpecialBranchPlaceholder();
        return;
    }
    ddlSpecialBranch.Enabled = true;
    SIM_SpecialBranch obj = new SIM_SpecialBranch();
    ddlSpecialBranch.DataSource = obj.GetDataTable(
                        "SIM_SpecialBranch_SearchForWeb",
                        "@LearningLevelID", ddlLearningLevel.SelectedValue,
                        "@TrainingLevelID", ddlTrainingLevel.SelectedValue);
    ddlSpecialBranch.DataValueField = "SpecialBranchID";
    ddlSpecialBranch.DataTextField = "SpecialBranchName";
    ddlSpecialBranch.DataBind();
    ddlSpecialBranch.Items.Insert(0, new ListItem("--Chọn--", ""));

